import React, { useState } from 'react';

export default function Product() {
  const [product, setProduct] = useState({
    id: 1,
    title: "Fjallraven - Foldsack No. 1 Backpack",
    price: 109.95,
    image: "https://fakestoreapi.com/img/81fPKd-2AYL._AC_SL1500_.jpg",
    description: "Perfect pack for everyday use.",
    rating: 3.9,
    qty: 1,
    brand: "Gucci"
  });

  const { image, brand, price, qty } = product;

  function handleInc() {
    setProduct((prev) => ({ ...prev, qty: prev.qty + 1 }));
  }

  function handleDec() {
    setProduct((prev) => ({ ...prev, qty: prev.qty > 1 ? prev.qty - 1 : 1 }));
  }

  return (
    <section className="container-fluid mt-3">
      <div className="col-3 m-auto">
        <div className="card">
          <div className="card-header">
            <img src={image} alt="product" className="img-fluid" />
          </div>
          <div className="card-body text-center">
            <h2>{brand}</h2>
            <h3>&#8377;{Math.trunc(price)}</h3>
            <h2>
              <i
                className="fa fa-minus-circle me-2 text-danger"
                onClick={handleDec}
                style={{ cursor: 'pointer' }}
              ></i>
              {qty}
              <i
                className="fa fa-plus-circle ms-2 text-success"
                onClick={handleInc}
                style={{ cursor: 'pointer' }}
              ></i>
            </h2>
          </div>
        </div>
      </div>
    </section>
  );
}
